            add(RpcUtils.getStatus(TSStatusCode.SUCCESS_STATUS));
            add(RpcUtils.getStatus(TSStatusCode.SUCCESS_STATUS));
            add(RpcUtils.getStatus(TSStatusCode.SUCCESS_STATUS));
        }
    };
    resp.setSubStatus(resExpected);
    statement.clearBatch();
    statement.addBatch("SET STORAGE GROUP TO root.ln.wf01.wt01");
