@Test
public void testMerge() throws WriteProcessException, QueryProcessException, IllegalPathException {
    for (int j = 21; j <= 30; j++) {
        TSRecord record = new TSRecord(j, deviceId);
        record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(j)));
        processor.insert(new InsertRowPlan(record));
        processor.asyncCloseAllWorkingTsFileProcessors();
    }
    processor.syncCloseAllWorkingTsFileProcessors();
    for (int j = 10; j >= 1; j--) {
        TSRecord record = new TSRecord(j, deviceId);
        record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(j)));
        processor.insert(new InsertRowPlan(record));
        processor.asyncCloseAllWorkingTsFileProcessors();
    }
    processor.syncCloseAllWorkingTsFileProcessors();
    processor.merge(true);
    while (processor.getTsFileManagement().isUnseqMerging) {
        // wait
    }
    QueryDataSource queryDataSource = processor.query(new PartialPath(deviceId), measurementId, context, null, null);
    Assert.assertEquals(10, queryDataSource.getSeqResources().size());
    Assert.assertEquals(0, queryDataSource.getUnseqResources().size());
    for (TsFileResource resource : queryDataSource.getSeqResources()) {
        Assert.assertTrue(resource.isClosed());
    }
    for (TsFileResource resource : queryDataSource.getUnseqResources()) {
        Assert.assertTrue(resource.isClosed());
    }
}

@Test
public void testWriteAndFlush() throws IOException, WriteProcessException, MetadataException {
    logger.info("testWriteAndFlush begin..");
    processor = new TsFileProcessor(storageGroup, SystemFileFactory.INSTANCE.getFile(filePath), sgInfo, SysTimeVersionController.INSTANCE, this::closeTsFileProcessor, (tsFileProcessor) -> true, true);
    TsFileProcessorInfo tsFileProcessorInfo = new TsFileProcessorInfo(sgInfo);
    processor.setTsFileProcessorInfo(tsFileProcessorInfo);
    this.sgInfo.initTsFileProcessorInfo(processor);
    tsFileProcessorInfo.addTSPMemCost(processor.getTsFileResource().calculateRamSize());
    SystemInfo.getInstance().reportStorageGroupStatus(sgInfo);
    List<TsFileResource> tsfileResourcesForQuery = new ArrayList<>();
    processor.query(deviceId, measurementId, dataType, encoding, props, context, tsfileResourcesForQuery);
    assertTrue(tsfileResourcesForQuery.isEmpty());
    for (int i = 1; i <= 100; i++) {
        TSRecord record = new TSRecord(i, deviceId);
        record.addTuple(DataPoint.getDataPoint(dataType, measurementId, String.valueOf(i)));
        processor.insert(new InsertRowPlan(record));
    }
    // query data in memory
    tsfileResourcesForQuery.clear();
    processor.query(deviceId, measurementId, dataType, encoding, props, context, tsfileResourcesForQuery);
    assertFalse(tsfileResourcesForQuery.get(0).getReadOnlyMemChunk().isEmpty());
    int num = 1;
    List<ReadOnlyMemChunk> memChunks = tsfileResourcesForQuery.get(0).getReadOnlyMemChunk();
    for (; num <= 100; num++) {
        for (ReadOnlyMemChunk chunk : memChunks) {
            IPointReader iterator = chunk.getPointReader();
            iterator.hasNextTimeValuePair();
            TimeValuePair timeValuePair = iterator.nextTimeValuePair();
            assertEquals(num, timeValuePair.getTimestamp());
            assertEquals(num, timeValuePair.getValue().getInt());
        }
    }
    // flush synchronously
    processor.syncFlush();
    tsfileResourcesForQuery.clear();
    processor.query(deviceId, measurementId, dataType, encoding, props, context, tsfileResourcesForQuery);
    assertTrue(tsfileResourcesForQuery.get(0).getReadOnlyMemChunk().isEmpty());
    assertEquals(1, tsfileResourcesForQuery.get(0).getChunkMetadataList().size());
    assertEquals(measurementId, tsfileResourcesForQuery.get(0).getChunkMetadataList().get(0).getMeasurementUid());
    assertEquals(dataType, tsfileResourcesForQuery.get(0).getChunkMetadataList().get(0).getDataType());
    processor.syncClose();
}

@Test
public void testWriteAndRestoreMetadata() throws IOException, WriteProcessException, MetadataException {
    logger.info("testWriteAndRestoreMetadata begin..");
    processor = new TsFileProcessor(storageGroup, SystemFileFactory.INSTANCE.getFile(filePath), sgInfo, SysTimeVersionController.INSTANCE, this::closeTsFileProcessor, (tsFileProcessor) -> true, true);
    TsFileProcessorInfo tsFileProcessorInfo = new TsFileProcessorInfo(sgInfo);
