    this.sgInfo.initTsFileProcessorInfo(processor);
    tsFileProcessorInfo.addTSPMemCost(processor.getTsFileResource().calculateRamSize());
    SystemInfo.getInstance().reportStorageGroupStatus(sgInfo);
    List<TsFileResource> tsfileResourcesForQuery = new ArrayList<>();
    processor.query(deviceId, measurementId, dataType, encoding, props, context, tsfileResourcesForQuery);
    assertTrue(tsfileResourcesForQuery.isEmpty());
    for (int i = 1; i <= 100; i++) {
        TSRecord record = new TSRecord(i, deviceId);
        record.addTuple(DataPoint.getDataPoint(dataType, measurementId, String.valueOf(i)));
        processor.insert(new InsertRowPlan(record));
    }
    // query data in memory
    tsfileResourcesForQuery.clear();
    processor.query(deviceId, measurementId, dataType, encoding, props, context, tsfileResourcesForQuery);
    assertFalse(tsfileResourcesForQuery.get(0).getReadOnlyMemChunk().isEmpty());
    int num = 1;
    List<ReadOnlyMemChunk> memChunks = tsfileResourcesForQuery.get(0).getReadOnlyMemChunk();
    for (ReadOnlyMemChunk chunk : memChunks) {
        IPointReader iterator = chunk.getPointReader();
        for (; num <= 100; num++) {
            iterator.hasNextTimeValuePair();
            TimeValuePair timeValuePair = iterator.nextTimeValuePair();
            assertEquals(num, timeValuePair.getTimestamp());
            assertEquals(num, timeValuePair.getValue().getInt());
        }
    }
    logger.info("syncFlush..");
    // flush synchronously
    processor.syncFlush();
    tsfileResourcesForQuery.clear();
    processor.query(deviceId, measurementId, dataType, encoding, props, context, tsfileResourcesForQuery);
    assertTrue(tsfileResourcesForQuery.get(0).getReadOnlyMemChunk().isEmpty());
    assertEquals(1, tsfileResourcesForQuery.get(0).getChunkMetadataList().size());
    assertEquals(measurementId, tsfileResourcesForQuery.get(0).getChunkMetadataList().get(0).getMeasurementUid());
    assertEquals(dataType, tsfileResourcesForQuery.get(0).getChunkMetadataList().get(0).getDataType());
    RestorableTsFileIOWriter tsFileIOWriter = processor.getWriter();
    Map<String, List<ChunkMetadata>> chunkMetaDataListInChunkGroups = tsFileIOWriter.getDeviceChunkMetadataMap();
    RestorableTsFileIOWriter restorableTsFileIOWriter = new RestorableTsFileIOWriter(SystemFileFactory.INSTANCE.getFile(filePath));
    Map<String, List<ChunkMetadata>> restoredChunkMetaDataListInChunkGroups = restorableTsFileIOWriter.getDeviceChunkMetadataMap();
    assertEquals(chunkMetaDataListInChunkGroups.size(), restoredChunkMetaDataListInChunkGroups.size());
    for (Map.Entry<String, List<ChunkMetadata>> entry1 : chunkMetaDataListInChunkGroups.entrySet()) {
        for (Map.Entry<String, List<ChunkMetadata>> entry2 : restoredChunkMetaDataListInChunkGroups.entrySet()) {
            assertEquals(entry1.getKey(), entry2.getKey());
            assertEquals(entry1.getValue().size(), entry2.getValue().size());
            for (int i = 0; i < entry1.getValue().size(); i++) {
                ChunkMetadata chunkMetaData = entry1.getValue().get(i);
                ChunkMetadata chunkMetadataRestore = entry2.getValue().get(i);
                assertEquals(chunkMetaData, chunkMetadataRestore);
            }
        }
    }
    restorableTsFileIOWriter.close();
    logger.info("syncClose..");
    processor.syncClose();
    //we need to close the tsfile writer first and then reopen it.
}

