            for (int i = 0; i < insertCnt; ) {
                for (int j = 0; j < batchSize; j++) {
                    userStmt.addBatch("INSERT INTO root.a(timestamp, b" + (privilegeCnt - 1) + ") VALUES (" + (i++ + 1) + ", 100)");
                }
                userStmt.executeBatch();
                userStmt.clearBatch();
            }
