public void selectAllSQLTest() throws ClassNotFoundException, SQLException {
    Class.forName(Config.JDBC_DRIVER_NAME);
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        boolean hasResultSet = statement.execute("select * from root");
        Assert.assertTrue(hasResultSet);
        int cnt;
        try (ResultSet resultSet = statement.getResultSet()) {
            cnt = 0;
            while (resultSet.next()) {
                assertEquals(TIMESTAMP + "", resultSet.getString(TIMESTAMP_STR));
                for (int i = 0; i < 10; i++) {
                    Assert.assertEquals(MathUtils.roundWithGivenPrecision(Float.parseFloat(VALUE), i), resultSet.getFloat(String.format("root.vehicle.%s.%s", "f0", "s" + i + "rle")), DELTA_FLOAT);
                    Assert.assertEquals(MathUtils.roundWithGivenPrecision(Float.parseFloat(VALUE), i), resultSet.getFloat(String.format("root.vehicle.%s.%s", "f0", "s" + i + "2f")), DELTA_FLOAT);
                    Assert.assertEquals(MathUtils.roundWithGivenPrecision(Double.parseDouble(VALUE), i), resultSet.getDouble(String.format("root.vehicle.%s.%s", "d0", "s" + i + "rle")), DELTA_DOUBLE);
                    Assert.assertEquals(MathUtils.roundWithGivenPrecision(Double.parseDouble(VALUE), i), resultSet.getDouble(String.format("root.vehicle.%s.%s", "d0", "s" + i + "2f")), DELTA_DOUBLE);
                }
                cnt++;
            }
            Assert.assertEquals(1, cnt);
        }
        statement.execute("flush");
        try (ResultSet resultSet = statement.executeQuery("select * from root")) {
            cnt = 0;
            while (resultSet.next()) {
                assertEquals(TIMESTAMP + "", resultSet.getString(TIMESTAMP_STR));
                for (int i = 0; i < 10; i++) {
                    BigDecimal b = new BigDecimal(VALUE);
                    Assert.assertEquals(b.setScale(i, RoundingMode.HALF_UP).floatValue(), resultSet.getFloat(String.format("root.vehicle.%s.%s", "f0", "s" + i + "rle")), DELTA_FLOAT);
                    Assert.assertEquals(b.setScale(i, RoundingMode.HALF_UP).floatValue(), resultSet.getFloat(String.format("root.vehicle.%s.%s", "f0", "s" + i + "2f")), DELTA_FLOAT);
                    Assert.assertEquals(b.setScale(i, RoundingMode.HALF_UP).doubleValue(), resultSet.getDouble(String.format("root.vehicle.%s.%s", "d0", "s" + i + "rle")), DELTA_DOUBLE);
                    Assert.assertEquals(b.setScale(i, RoundingMode.HALF_UP).doubleValue(), resultSet.getDouble(String.format("root.vehicle.%s.%s", "d0", "s" + i + "2f")), DELTA_DOUBLE);
                }
                cnt++;
            }
            Assert.assertEquals(1, cnt);
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

