@Test
public void testFlushNotExistGroupNoData() throws ClassNotFoundException {
    Class.forName(Config.JDBC_DRIVER_NAME);
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        statement.execute("SET STORAGE GROUP TO root.noexist.nodatagroup1");
        try {
            statement.execute("FLUSH root.noexist.nodatagroup1,root.notExistGroup1,root.notExistGroup2");
        } catch (SQLException sqe) {
            StorageGroupNotSetException tmpsgnse = new StorageGroupNotSetException("root.notExistGroup1,root.notExistGroup2");
            SQLException sqlException = new SQLException(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": " + tmpsgnse.getMessage());
            assertEquals(sqlException.getMessage(), sqe.getMessage());
        }
    } catch (Exception e) {
        logger.error("testFlushNotExistGroupNoData failed", e);
        fail(e.getMessage());
    }
}

