@Test
public void lastCacheUpdateTest() throws SQLException, MetadataException {
    String[] retArray = new String[] { "500,root.ln.wf01.wt01.temperature,22.1", "500,root.ln.wf01.wt01.status,false", "500,root.ln.wf01.wt01.id,5", "700,root.ln.wf01.wt01.temperature,33.1", "700,root.ln.wf01.wt01.status,false", "700,root.ln.wf01.wt01.id,3", "700,root.ln.wf01.wt01.temperature,33.1", "700,root.ln.wf01.wt01.status,false", "700,root.ln.wf01.wt01.id,3" };
    try (Connection connection = DriverManager.getConnection("jdbc:iotdb://127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        boolean hasResultSet = statement.execute("select last temperature,status,id from root.ln.wf01.wt01");
        assertTrue(hasResultSet);
        int cnt = 0;
        try (ResultSet resultSet = statement.getResultSet()) {
            while (resultSet.next()) {
                String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(TIMESEIRES_STR) + "," + resultSet.getString(VALUE_STR);
                Assert.assertEquals(retArray[cnt], ans);
                cnt++;
            }
        }
        MeasurementMNode node = (MeasurementMNode) IoTDB.metaManager.getNodeByPath(new PartialPath("root.ln.wf01.wt01.temperature"));
        node.resetCache();
        statement.execute("insert into root.ln.wf01.wt01(time, temperature, status, id) values(700, 33.1, false, 3)");
        // Last cache is updated with above insert sql
        long time = node.getCachedLast().getTimestamp();
        Assert.assertEquals(700, time);
        hasResultSet = statement.execute("select last temperature,status,id from root.ln.wf01.wt01");
        assertTrue(hasResultSet);
        try (ResultSet resultSet = statement.getResultSet()) {
            while (resultSet.next()) {
                String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(TIMESEIRES_STR) + "," + resultSet.getString(VALUE_STR);
                Assert.assertEquals(retArray[cnt], ans);
                cnt++;
            }
        }
        statement.execute("insert into root.ln.wf01.wt01(time, temperature, status, id) values(600, 19.1, false, 1)");
        // Last cache is not updated with above insert sql
        time = node.getCachedLast().getTimestamp();
        Assert.assertEquals(700, time);
        hasResultSet = statement.execute("select last temperature,status,id from root.ln.wf01.wt01");
        assertTrue(hasResultSet);
        try (ResultSet resultSet = statement.getResultSet()) {
            while (resultSet.next()) {
                String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(TIMESEIRES_STR) + "," + resultSet.getString(VALUE_STR);
                Assert.assertEquals(retArray[cnt], ans);
                cnt++;
            }
        }
        Assert.assertEquals(cnt, retArray.length);
    }
}

