@Test
public void testRemoveNoPartition() throws StorageEngineException, IllegalPathException {
    StorageEngine.getInstance().removePartitions(new PartialPath("root.test1"), (storageGroupName, timePartitionId) -> false);
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        try (ResultSet resultSet = statement.executeQuery("SELECT * FROM root.test1")) {
            int count = 0;
            while (resultSet.next()) {
                assertEquals(count / 2 * 100 + count % 2 * 50, resultSet.getLong(1));
                assertEquals(count / 2 * 100 + count % 2 * 50, resultSet.getLong(2));
                count++;
            }
            assertEquals(20, count);
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

