@Test
public void selectAllTest() throws ClassNotFoundException {
    String[] retArray = new String[] { "1,1,1", "2,2,2", "3,3,3", "4,4,4", "5,5,0", "6,6,1", "7,7,2", "8,8,3", "9,9,4" };
    String selectSql = "select * from root";
    Class.forName(Config.JDBC_DRIVER_NAME);
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement1 = connection.createStatement();
        Statement statement2 = connection.createStatement()) {
        statement1.setFetchSize(10);
        boolean hasResultSet1 = statement1.execute(selectSql);
        Assert.assertTrue(hasResultSet1);
        ResultSet resultSet1 = statement1.getResultSet();
        int cnt1 = 0;
        while (resultSet1.next() && cnt1 < 5) {
            StringBuilder builder = new StringBuilder();
            builder.append(resultSet1.getString(TestConstant.TIMESTAMP_STR)).append(",").append(resultSet1.getString("root.fans.d0.s0")).append(",").append(resultSet1.getString("root.fans.d1.s0"));
            Assert.assertEquals(retArray[cnt1], builder.toString());
            cnt1++;
        }
        statement2.setFetchSize(10);
        boolean hasResultSet2 = statement2.execute(selectSql);
        Assert.assertTrue(hasResultSet2);
        ResultSet resultSet2 = statement2.getResultSet();
        int cnt2 = 0;
        while (resultSet2.next()) {
            StringBuilder builder = new StringBuilder();
            builder.append(resultSet2.getString(TestConstant.TIMESTAMP_STR)).append(",").append(resultSet2.getString("root.fans.d0.s0")).append(",").append(resultSet2.getString("root.fans.d1.s0"));
            Assert.assertEquals(retArray[cnt2], builder.toString());
            cnt2++;
        }
        Assert.assertEquals(9, cnt2);
        // use do-while instead of while because in the previous while loop, we have executed the next function,
        // and the cursor has been moved to the next position, so we should fetch that value first.
        do {
            StringBuilder builder = new StringBuilder();
            builder.append(resultSet1.getString(TestConstant.TIMESTAMP_STR)).append(",").append(resultSet1.getString("root.fans.d0.s0")).append(",").append(resultSet1.getString("root.fans.d1.s0"));
            Assert.assertEquals(retArray[cnt1], builder.toString());
            cnt1++;
        } while (resultSet1.next());
        // Although the statement2 has the same sql as statement1, they shouldn't affect each other.
        // So the statement1's ResultSet should also have 9 rows in total.
        Assert.assertEquals(9, cnt1);
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testMerge() throws SQLException, InterruptedException {
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        statement.execute("set storage group to root.demo");
        statement.execute("create timeseries root.demo.d1.s1 with datatype=INT64,encoding=RLE");
        statement.execute("create timeseries root.demo.d1.s2 with datatype=INT64,encoding=RLE");
        statement.execute("create timeseries root.demo.d1.s3 with datatype=INT64,encoding=RLE");
        statement.execute("insert into root.demo.d1(time,s1,s2) values(1,1,2)");
        statement.execute("flush");
        statement.execute("insert into root.demo.d1(time,s3) values(1,1)");
        statement.execute("flush");
        try (ResultSet set = statement.executeQuery("SELECT * FROM root")) {
            int cnt = 0;
            while (set.next()) {
                cnt++;
                assertEquals(1, set.getLong("root.demo.d1.s3"));
            }
            assertEquals(1, cnt);
        }
        statement.execute("merge");
        Thread.sleep(1000);
        // before merge completes
        try (ResultSet set = statement.executeQuery("SELECT * FROM root")) {
            int cnt = 0;
            while (set.next()) {
                cnt++;
                assertEquals(1, set.getLong("root.demo.d1.s3"));
            }
            assertEquals(1, cnt);
        }
        // after merge completes
        statement.execute("DELETE FROM root.demo.d1");
    }
}

