    Assert.assertEquals("For delete statement, where clause can only contain atomic expressions like : " + "time > XXX, time <= XXX, or two atomic expressions connected by 'AND'", errorMsg);
    sql = "delete from root.d1.s1 where time>=1 or time < 3";
    errorMsg = null;
    try {
        parseDriver.parse(sql, ZoneId.systemDefault());
    } catch (SQLParserException e) {
        errorMsg = e.getMessage();
    }
    Assert.assertEquals("For delete statement, where clause can only contain atomic expressions like : " + "time > XXX, time <= XXX, or two atomic expressions connected by 'AND'", errorMsg);
    String sql7 = "delete from root.d1.s1 where time = 1 and time < -1";
    errorMsg = null;
    try {
        parseDriver.parse(sql7, ZoneId.systemDefault());
    } catch (RuntimeException e) {
        errorMsg = e.getMessage();
    }
    Assert.assertEquals("Invalid delete range: [1, -2]", errorMsg);
    sql = "delete from root.d1.s1 where time > 5 and time <= 0";
    errorMsg = null;
    try {
        parseDriver.parse(sql, ZoneId.systemDefault());
    } catch (SQLParserException e) {
        errorMsg = e.getMessage();
    }
    Assert.assertEquals("Invalid delete range: [6, 0]", errorMsg);
