    assertTrue(dataSet.hasNext());
    assertEquals("12\t102", dataSet.next().toString());
    assertFalse(dataSet.hasNext());
}

@Test
public void groupByFillTest() throws Exception {
    QueryPlan queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select last_value(s0) from root.vehicle.* group by ([0,20), 1ms) fill (int32[Previous]) order by time desc");
    QueryDataSet dataSet = queryExecutor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    assertTrue(dataSet.hasNext());
    assertEquals("19\t8", dataSet.next().toString());
    for (int i = 0; i < 10; i++) {
        dataSet.hasNext();
        dataSet.next();
    }
    assertTrue(dataSet.hasNext());
    assertEquals("8\t8", dataSet.next().toString());
    for (int i = 7; i > -1; i--) {
        assertTrue(dataSet.hasNext());
        if (i > 5) {
            assertEquals(i + "\t" + i, dataSet.next().toString());
        } else if (i > 0) {
            assertEquals(i + "\t" + 1, dataSet.next().toString());
        } else {
            assertEquals(i + "\t" + "null", dataSet.next().toString());
        }
    }
}

