@Test
public void testGroupByLevel() throws Exception {
    QueryPlan queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select count(s1) from root.test.* group by level=1");
    QueryDataSet dataSet = queryExecutor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    assertTrue(dataSet.hasNext());
    assertEquals("0\t12", dataSet.next().toString());
    queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select count(s1) from root.test.* group by level=0");
    dataSet = queryExecutor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    assertTrue(dataSet.hasNext());
    assertEquals("0\t12", dataSet.next().toString());
    queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select count(s1) from root.test.* group by level=6");
    dataSet = queryExecutor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    assertTrue(dataSet.hasNext());
    assertEquals("0\t12", dataSet.next().toString());
    // multi paths
    queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select count(s1) from root.test.*,root.vehicle.* group by level=1");
    dataSet = queryExecutor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    assertTrue(dataSet.hasNext());
    assertEquals("0\t12\t10", dataSet.next().toString());
    // with multi result
    queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select count(s1), count(s0) from root.test.* group by level=6");
    dataSet = queryExecutor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    assertTrue(dataSet.hasNext());
    assertEquals("0\t12\t12", dataSet.next().toString());
    // with multi result
    queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select count(s1), count(s3) from root.test.* group by level=2");
    dataSet = queryExecutor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    assertTrue(dataSet.hasNext());
    assertEquals("0\t13", dataSet.next().toString());
    // with double quotation mark
    queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select count(\"s3.xy\") from root.test.* group by level=2");
    dataSet = queryExecutor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    assertTrue(dataSet.hasNext());
    assertEquals("0\t1", dataSet.next().toString());
    // not count
    try {
        queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select sum(s0) from root.test.* group by level=6");
        fail();
    } catch (Exception e) {
        assertEquals("group by level only support count now.", e.getMessage());
    }
}

