@Test
public void testGetIntMinBitWidth() {
    List<Integer> uvIntList = new ArrayList<Integer>();
    uvIntList.add(0);
    assertEquals(1, ReadWriteForEncodingUtils.getIntMaxBitWidth(uvIntList));
    uvIntList.add(1);
    assertEquals(1, ReadWriteForEncodingUtils.getIntMaxBitWidth(uvIntList));
    int uvInt = 123;
    for (int i = 0; i < 10; i++) {
